#!/usr/bin/env python3
"""Publish only fixed public test labels; never expose diagnostic log content."""
import re
import sys
from pathlib import Path

SAFE_LABELS = {'existing article discussions keep their exact real issue mappings': 'existing article discussions keep their exact real issue mappings', 'pending setup fixture keeps on-site comments primary without authentication secrets': 'pending setup fixture keeps on-site comments primary without authentication secrets', 'new article comments use provider mapping without inventing an issue or outbound posting link': 'new article comments use provider mapping without inventing an issue or outbound posting link', 'configured discussions render only the real repo metadata and an on-site container': 'configured discussions render only the real repo metadata and an on-site container', 'build rejects malformed comment repositories and issue configuration': 'build rejects malformed comment repositories and issue configuration', 'English revisions preserve all six author-owned Chinese blocks byte for byte': 'English revisions preserve all six author-owned Chinese blocks byte for byte', 'all translated pages retain source links and images with English hidden until selected': 'all translated pages retain source links and images with English hidden until selected', 'known malformed QR resource links render correctly without altering Markdown input': 'known malformed QR resource links render correctly without altering Markdown input', 'same renderer preserves math, code, table and safe diagram text': 'same renderer preserves math, code, table and safe diagram text', 'bilingual source has only Chinese visible and distinct English IDs, shared text survives': 'bilingual source has only Chinese visible and distinct English IDs, shared text survives', 'malformed language delimiters fail visibly instead of losing content': 'malformed language delimiters fail visibly instead of losing content', 'recovered Chinese article bodies remain byte-equivalent apart from surrounding whitespace': 'recovered Chinese article bodies remain byte-equivalent apart from surrounding whitespace', 'post CLI keeps draft preimages and refuses replacement or path traversal': 'post CLI keeps draft preimages and refuses replacement or path traversal', 'published Markdown, HTML, page covers and reference links retain uploads; drafts and code do not': 'published Markdown, HTML, page covers and reference links retain uploads; drafts and code do not', 'query strings and encoded names resolve without authorizing traversal or off-site URLs': 'query strings and encoded names resolve without authorizing traversal or off-site URLs', 'route filtering updates after publication and never alters local assets or legacy images': 'route filtering updates after publication and never alters local assets or legacy images', 'real Hexo output excludes a draft upload and includes it after publication, preserving its local bytes': 'real Hexo output excludes a draft upload and includes it after publication, preserving its local bytes', 'saving preserves exact Markdown and archives the preimage before replacing it': 'saving preserves exact Markdown and archives the preimage before replacing it', 'draft creation stays in drafts and duplicate titles preserve the first draft': 'draft creation stays in drafts and duplicate titles preserve the first draft', 'path traversal, absolute paths, hidden paths and symlinks cannot expose files': 'path traversal, absolute paths, hidden paths and symlinks cannot expose files', 'image uploads validate MIME and signatures and remain in the image subtree': 'image uploads validate MIME and signatures and remain in the image subtree', 'preview removes both standard and legacy Hexo frontmatter without changing the saved input': 'preview removes both standard and legacy Hexo frontmatter without changing the saved input', 'HTTP API requires the current token and rejects foreign origins and rebinding hosts': 'HTTP API requires the current token and rejects foreign origins and rebinding hosts', 'concurrent HTTP saves detect stale versions and never silently overwrite': 'concurrent HTTP saves detect stale versions and never silently overwrite', 'preview uses the production renderer contract and images load in a script-disabled sandbox': 'preview uses the production renderer contract and images load in a script-disabled sandbox'}
SAFE_FILES = ['tests/comments.test.cjs', 'tests/english.test.cjs', 'tests/markdown.test.cjs', 'tests/post.test.cjs', 'tests/public-assets.test.cjs', 'tools/writer/test.mjs']

log = Path(sys.argv[1]).read_text(errors="replace")
failed = re.findall(r"^not ok \d+ - (.+)$", log, re.MULTILINE)
for candidate in failed:
    label = SAFE_LABELS.get(candidate)
    if label is None:
        name = next((name for name in SAFE_FILES if candidate == name or candidate.endswith("/" + name)), None)
        label = "Test file could not complete: " + name if name else "A test could not complete; see the account-controlled job log."
    print("::error title=Website test failed::" + label)
if not failed:
    print("::error title=Website test failed::Tests did not complete; see the account-controlled job log.")
